js='''const menuButton=document.querySelector('.menu-btn'),menu=document.querySelector('#menu');function closeMenu(){menu.classList.remove('open');menuButton.setAttribute('aria-expanded','false');menuButton.textContent='Menü'}menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));menu.classList.toggle('open',open);menuButton.textContent=open?'Bezárás':'Menü'});menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.classList.contains('open')){closeMenu();menuButton.focus()}});window.matchMedia('(min-width:761px)').addEventListener('change',e=>{if(e.matches)closeMenu()});document.querySelectorAll('form[data-demo]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();form.querySelector('[role=status]').textContent=form.dataset.demo==='newsletter'?'Ez egy bemutató: nem történt feliratkozás. A Kisokos letöltése még nem elérhető.':'Ez egy bemutató: az üzeneted nem került elküldésre, időpontkérés nem történt.'}));'''
(assets/'site.js').write_text(js,encoding='utf-8')
data=json.loads((root/'.webprojekt/website-images.json').read_text(encoding='utf-8'))
def photo(slug,high=False):
 d=data[slug];v=d['variants'][0];ss=', '.join(f"{x['path']} {x['width']}w" for x in reversed(d['variants']))
 return f'<img src="{v["path"]}" srcset="{ss}" sizes="(max-width:760px) calc(100vw - 40px), 560px" width="{v["width"]}" height="{v["height"]}" alt="{d["alt"]}" decoding="async" '+('fetchpriority="high"' if high else 'loading="lazy"')+'>'
def extract(pattern):
 match=re.search(pattern,source,re.S);assert match,pattern;return match[0]
contact=extract(r'<section class="section wrap contact".*?</section>')
contact=re.sub(r'<a href="#adatkezeles" data-privacy', '<a href="adatkezeles.html"',contact)
faq=extract(r'<section class="section wrap" style="padding-top:0">.*?</section>')
reviews=extract(r'<section class="testimonials".*?</section>')
process=extract(r'<section class="section wrap" id="folyamat">.*?</section>')
footer=extract(r'<footer class="footer">.*?</footer>')
footer=re.sub(r'<button type="button" data-privacy>Adatkezelési tájékoztató</button>','<a href="adatkezeles.html">Adatkezelési tájékoztató</a>',footer)
for old,new in [('#tartalom','index.html'),('#kezelesek','kezelesek.html'),('#rolunk','rolunk.html'),('#kapcsolat','kapcsolat.html')]:footer=footer.replace(f'href="{old}"',f'href="{new}"')
def header(active):
 links=''.join(f'<a href="{name}"'+(' aria-current="page"' if name==active else '')+f'>{label}</a>' for name,label in [('index.html','Főoldal'),('kezelesek.html','Kezelések'),('rolunk.html','Rólunk'),('kapcsolat.html','Kapcsolat')])
 target='#kapcsolat' if active!='adatkezeles.html' else 'kapcsolat.html#kapcsolat'
 return '<a class="skip" href="#tartalom">Ugrás a tartalomra</a><header class="header"><div class="wrap header-inner"><a href="index.html" aria-label="Eliza Beauty Salon, főoldal"><img class="logo" src="logo/logo.svg" alt="Eliza Beauty Salon" width="120" height="74"></a><button class="menu-btn" aria-expanded="false" aria-controls="menu" type="button">Menü</button><nav class="nav" id="menu" aria-label="Fő navigáció">'+links+f'<a class="btn" href="{target}">Időpontot kérek</a></nav></div></header>'
def hero(label,title,description,slug):
 return f'<section class="page-hero wrap"><nav class="breadcrumbs" aria-label="Morzsamenü"><a href="index.html">Főoldal</a> / <span>{label}</span></nav><div class="page-hero-grid"><div><div class="kicker">{label}</div><h1>{title}</h1><p>{description}</p><div class="actions"><a class="btn" href="#kapcsolat">Időpontot kérek</a></div></div><figure>{photo(slug,True)}</figure></div></section>'
def page(filename,title,description,main):
 url=domain+('' if filename=='index.html' else filename)
 faq_items=[]
 for q,a in re.findall(r'<details><summary>(.*?)</summary><p>(.*?)</p></details>',main,re.S):
  text=lambda x:unescape(re.sub('<[^>]+>','',x)).strip()
  faq_items.append({'@type':'Question','name':text(q),'acceptedAnswer':{'@type':'Answer','text':text(a)}})
 schema=[{'@context':'https://schema.org','@type':'WebPage','url':url,'name':title,'description':description,'inLanguage':'hu-HU','about':{'@type':'BeautySalon','name':'Eliza Beauty Salon'}}]
 if faq_items:schema.append({'@context':'https://schema.org','@type':'FAQPage','mainEntity':faq_items})
 head=f'''<!doctype html><html lang="hu"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><meta name="description" content="{escape(description)}"><link rel="canonical" href="{url}"><link rel="icon" href="logo/favicon.svg"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@500;600&family=Jost:wght@400;500&display=swap" rel="stylesheet"><link href="assets/site.css" rel="stylesheet"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(description)}"><meta property="og:url" content="{url}"><meta property="og:type" content="website"><meta property="og:locale" content="hu_HU"><meta property="og:site_name" content="Eliza Beauty Salon"><meta property="og:image" content="{domain}images/website/social-preview.jpg"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Kozmetikai arckezelés"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{escape(title)}"><meta name="twitter:description" content="{escape(description)}"><meta name="twitter:image" content="{domain}images/website/social-preview.jpg"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script></head><body>'''
 html=head+header(filename)+'<main id="tartalom">'+main+'</main>'+footer+'<script src="assets/site.js" defer></script></body></html>'
 (root/filename).write_text(html,encoding='utf-8')

